//! Phase-0 oracle: decode Parquet bytes written by the Python
//! `lake.storage.parquet.ParquetWriter` and assert the pinned Arrow schema,
//! metadata, and logical rows.
//!
//! Fixtures are generated by `src/lake/tests/oracle/generate.py`.

use std::fs::File;

use arrow_array::{
    Array, Decimal128Array, Int64Array, ListArray, StringArray, TimestampNanosecondArray,
    UInt32Array, UInt64Array,
};
use arrow_schema::DataType as ArrowType;
use lake_contracts::{
    schema_for, AssetClass, DataType, DateTime, Decimal18, SCHEMA_METADATA_KEY,
    SCHEMA_VERSION_METADATA_KEY,
};
use parquet::arrow::arrow_reader::ParquetRecordBatchReaderBuilder;
use serde_json::Value;

fn manifest() -> Vec<Value> {
    serde_json::from_str(include_str!("oracle/parquet_manifest.json")).expect("manifest")
}

#[test]
fn python_parquet_files_decode_to_the_pinned_schema_and_rows() {
    let entries = manifest();
    assert_eq!(entries.len(), 6);
    for entry in &entries {
        let asset_class =
            AssetClass::from_value(entry["asset_class"].as_str().expect("asset")).expect("asset");
        let data_type =
            DataType::from_value(entry["data_type"].as_str().expect("type")).expect("type");
        let symbol = entry["symbol"].as_str().expect("symbol");
        let relative = entry["file"].as_str().expect("file");
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests")
            .join("oracle")
            .join(relative);
        let builder = ParquetRecordBatchReaderBuilder::try_new(File::open(&path).expect("file"))
            .expect("builder");
        let expected_schema = schema_for(asset_class, data_type).expect("schema");
        assert_eq!(
            builder.schema().fields().len(),
            expected_schema.fields().len(),
            "{relative} field count"
        );
        for (expected, actual) in expected_schema
            .fields()
            .iter()
            .zip(builder.schema().fields())
        {
            assert_eq!(expected.name(), actual.name(), "{relative} field name");
            assert_eq!(
                expected.data_type(),
                actual.data_type(),
                "{relative} field type for {}",
                expected.name()
            );
            assert_eq!(
                expected.is_nullable(),
                actual.is_nullable(),
                "{relative} nullability for {}",
                expected.name()
            );
        }
        let kv = builder
            .metadata()
            .file_metadata()
            .key_value_metadata()
            .expect("file key-value metadata");
        let find = |key: &str| {
            kv.iter()
                .find(|entry| entry.key == key)
                .and_then(|entry| entry.value.clone())
        };
        assert_eq!(
            find(SCHEMA_METADATA_KEY).as_deref(),
            Some(format!("{}.{}", asset_class.value(), data_type.value()).as_str())
        );
        assert_eq!(find(SCHEMA_VERSION_METADATA_KEY).as_deref(), Some("1"));

        let expected_rows = entry["rows"].as_array().expect("rows");
        let mut actual_rows = Vec::new();
        for batch in builder.build().expect("reader") {
            let batch = batch.expect("batch");
            for row_index in 0..batch.num_rows() {
                actual_rows.push(batch.slice(row_index, 1));
            }
        }
        assert_eq!(
            actual_rows.len(),
            expected_rows.len(),
            "{relative} row count"
        );
        for (index, expected_row) in expected_rows.iter().enumerate() {
            let batch = &actual_rows[index];
            for (field_index, field) in expected_schema.fields().iter().enumerate() {
                let expected_value = &expected_row[field.name()];
                let column = batch.column(field_index);
                compare_value(
                    relative,
                    field.name(),
                    field.data_type(),
                    column,
                    0,
                    expected_value,
                );
            }
        }
        assert_eq!(
            symbol,
            entry["symbol"].as_str().expect("symbol"),
            "manifest symbol self-check"
        );
    }
}

fn compare_value(
    file: &str,
    name: &str,
    data_type: &ArrowType,
    column: &arrow_array::ArrayRef,
    index: usize,
    expected: &Value,
) {
    if expected.is_null() {
        assert!(column.is_null(index), "{file}:{name} expected null");
        return;
    }
    match data_type {
        ArrowType::Timestamp(_, _) => {
            let array = column
                .as_any()
                .downcast_ref::<TimestampNanosecondArray>()
                .expect("timestamp column");
            let actual = DateTime::from_nanos(array.value(index));
            let expected = DateTime::parse_iso_utc(expected.as_str().expect("timestamp string"))
                .expect("expected timestamp");
            assert_eq!(actual, expected, "{file}:{name} timestamp mismatch");
        }
        ArrowType::Utf8 => {
            let array = column
                .as_any()
                .downcast_ref::<StringArray>()
                .expect("string column");
            assert_eq!(
                array.value(index),
                expected.as_str().expect("string"),
                "{file}:{name}"
            );
        }
        ArrowType::UInt32 => {
            let array = column
                .as_any()
                .downcast_ref::<UInt32Array>()
                .expect("u32 column");
            assert_eq!(
                u64::from(array.value(index)),
                expected.as_u64().expect("u32 value"),
                "{file}:{name}"
            );
        }
        ArrowType::UInt64 => {
            let array = column
                .as_any()
                .downcast_ref::<UInt64Array>()
                .expect("u64 column");
            assert_eq!(
                array.value(index),
                expected.as_u64().expect("u64 value"),
                "{file}:{name}"
            );
        }
        ArrowType::Int64 => {
            let array = column
                .as_any()
                .downcast_ref::<Int64Array>()
                .expect("i64 column");
            assert_eq!(
                array.value(index),
                expected.as_i64().expect("i64 value"),
                "{file}:{name}"
            );
        }
        ArrowType::Decimal128(_, _) => {
            let array = column
                .as_any()
                .downcast_ref::<Decimal128Array>()
                .expect("decimal column");
            let actual = Decimal18::from_unscaled_unchecked(array.value(index));
            assert_eq!(
                actual.to_canonical_string(),
                expected.as_str().expect("decimal string"),
                "{file}:{name}"
            );
        }
        ArrowType::List(_) => {
            let array = column
                .as_any()
                .downcast_ref::<ListArray>()
                .expect("list column");
            let values = array.value(index);
            let strings = values
                .as_any()
                .downcast_ref::<StringArray>()
                .expect("string list");
            let actual: Vec<&str> = (0..strings.len()).map(|i| strings.value(i)).collect();
            let expected: Vec<&str> = expected
                .as_array()
                .expect("list value")
                .iter()
                .map(|item| item.as_str().expect("list item"))
                .collect();
            assert_eq!(actual, expected, "{file}:{name}");
        }
        other => panic!("{file}:{name} unexpected arrow type {other:?}"),
    }
}
